static void Gen_trgeometry_body_point_trajectory(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const int32_t crs_g = GeometryCrsSrid(args.data[1].GetType());
    BinaryExecutor::ExecuteWithNulls<string_t, string_t, string_t>(args.data[0], args.data[1], result, args.size(),
        [&](string_t in_t, string_t in_g, ValidityMask &mask, idx_t idx) -> string_t {
            Temporal *t = BlobToTemporal(in_t);
            GSERIALIZED *gs = GeometryToGSerialized(in_g, crs_g ? crs_g : tspatial_srid(t));
            if (MEOS_FLAGS_GET_GEODETIC(t->flags)) {
                GSERIALIZED *gs_geog = geom_to_geog(gs);
                free(gs); gs = gs_geog;
            }
            Temporal *r = (Temporal *) trgeometry_body_point_trajectory(t, gs);
            free(t); free(gs);
            return TemporalToBlobN(result, r, mask, idx);
        });
}


// ===== @ingroup meos_s2cell_inout =====
static void Gen_ts2cell_in(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    UnaryExecutor::ExecuteWithNulls<string_t, string_t>(args.data[0], result, args.size(),
        [&](string_t in, ValidityMask &mask, idx_t idx) -> string_t {
            Temporal *r = ts2cell_in(in.GetString().c_str());
            return TemporalToBlobN(result, r, mask, idx);
        });
}

static void Gen_ts2cell_out(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    UnaryExecutor::Execute<string_t, string_t>(args.data[0], result, args.size(),
        [&](string_t in) {
            Temporal *t = BlobToTemporal(in);
            char * r = ts2cell_out(t);
            free(t);
            return TakeCString(result, r);
        });
}


